/* v2.4 — remaining authentic-question item-level deep explanations. Generated from user-supplied exam bank. */

/* deep_batch_109_86731.js */
window.ITEM_DEEP=Object.assign(window.ITEM_DEEP||{}, {
"H109_86731_01":{teach:"來路不明減肥藥常混入中樞刺激劑、利尿劑、瀉藥或未核准成分，劑量與純度不穩定，可能造成心血管、神經與精神風險。成癮性藥物反覆使用可產生依賴與耐受性，需要更高劑量才能達到相同效果。B、C肝與性病是血液／性接觸等傳染，不是『大多數減肥藥使用者都會被傳染』。",solve:"1成分不穩定可致嚴重傷害、2依賴、3耐受都正確；4把感染症當成減肥藥直接結果，錯。故選A＝123。",options:["A 正確，123。","B 含4錯誤。","C 含4且漏3。","D 含4且漏2。"],memory:"成癮藥物三關鍵：不明成分、依賴、耐受；感染B/C肝不是藥物本身必然造成。"},
"H109_86731_02":{teach:"藥品許可證字號可看出管理類別。『衛署成藥製字第○○○○號』中的『成藥』已直接指出是成藥；『製字』表示國內製造核准。這類許可證字樣是辨識合法藥品的重要線索。",solve:"字號已寫『成藥製字』，所以選A成藥。",options:["A 正確。『成藥製字』就是核准製造的成藥許可證。","B 指示藥會有不同許可管理標示。","C 食品不會用此藥品許可證字號。","D 處方藥也不會以『成藥』標示。"],memory:"許可證字號先看關鍵字：『成藥製字』＝成藥＋國內製造。"},
"H109_86731_03":{teach:"安寧緩和醫療的目的不是安樂死，而是在末期疾病中減輕痛苦、提供支持性照護，並尊重病人對CPR、維生醫療等選擇。病人可預立意願，且意願可依法變更／撤回；在符合條件時，無法表達的末期病人也有法定代理／親屬同意機制。",solve:"C正確描述安寧緩和醫療：以緩解性、支持性照護減輕末期病人痛苦，並可選擇不施行CPR。A把它等同安樂死；B說不能改意願；D說親屬永遠不能代理，皆錯。",options:["A 錯。安寧療護不等於安樂死。","B 錯。預立意願可依規定撤回或變更。","C 正確。重點是緩解痛苦、支持照護與尊重不施行CPR等意願。","D 錯。在法定條件下可有親屬同意／代理機制。"],memory:"安寧＝不以治癒為唯一目標，而是減苦、支持、尊重意願；≠安樂死。"},
"H109_86731_04":{teach:"壓力是個體對壓力源的評估與反應，會同時影響心理與生理。適度壓力可提高動機與表現，太低或太高都可能使效能下降（倒U型）。壓力啟動交感神經與腎上腺素，通常心跳加快、肌肉張力上升；日常小壓力也會累積。",solve:"1正確，3正確；2、4、5都把壓力生理影響講反或否定累積效應，所以選B＝13。",options:["A 含2錯。","B 正確，1與3。","C 含4錯。","D 4、5皆錯。"],memory:"壓力：心身都會反應；適中最好；交感↑＝心跳快、肌張力高；小壓力也會累積。"},
"H109_86731_05":{teach:"性喚起造成勃起是正常自主生理反應，不代表一定要進一步性行為。青少年面對性刺激可透過轉移話題、改變情境、到公共場所活動等方式降低衝動與壓力。若刻意進入私密、無人監督的環境，反而增加界線模糊與衝動行為風險。",solve:"C建議兩人到志明家看書，雖名義上看書，但從高刺激情境轉往更私密空間，不利健康界線管理，因此最不妥。",options:["A 正確。勃起可是不由意志控制的正常生理反應。","B 合理。尊重隱私、轉移話題可降低尷尬。","C 不妥，故為答案。私密居家環境可能提高衝動與界線風險。","D 較合適。公共場所用餐可轉換情境。"],memory:"性衝動管理不是羞辱生理反應，而是『換情境、守界線、選公共安全空間』。"},
"H109_86731_06":{teach:"所謂『恐怖情人』通常指親密關係中的控制與暴力警訊：過度監控行蹤、隔離社交、毀物或肢體暴力、威脅自傷來操控對方等。單純抱怨、碎念雖可能讓人不舒服，但不能單憑這點就等同暴力控制型伴侶。",solve:"B、C、D都是明顯控制／暴力／情緒勒索警訊；A『一直碎碎念』單獨而言不足以構成典型恐怖情人特質，因此選A。",options:["A 不是典型核心警訊，故為答案；需看是否伴隨控制與威脅。","B 是控制行蹤與限制自由的警訊。","C 是物品破壞與肢體暴力警訊。","D 是以自傷威脅造成罪惡感的情緒勒索／控制。"],memory:"危險關係看『控制、隔離、威脅、暴力』，不是只看會不會抱怨。"},
"H109_86731_07":{teach:"Sternberg愛情三角：親密（情感連結）、激情（性／浪漫吸引）、承諾（決定維持關係）。浪漫之愛＝親密＋激情、缺承諾；友誼／伴侶之愛常是親密＋承諾；情慾／迷戀之愛主要只有激情；成熟／圓滿之愛三者兼具。",solve:"小羅與女友有親密與激情，但拒絕結婚且持續與他人性行為，顯示缺乏承諾，所以是浪漫之愛D。",options:["A 友誼／伴侶之愛偏親密＋承諾，缺激情，與題幹不符。","B 情慾之愛主要只有激情，題幹仍有長期親密互動。","C 成熟／圓滿之愛需親密＋激情＋承諾，題幹明顯缺承諾。","D 正確。親密＋激情、無承諾＝浪漫之愛。"],memory:"愛情三角：浪漫＝親密＋激情；圓滿＝三者全有。"},
"H109_86731_08":{teach:"我的餐盤口訣：每天早晚一杯奶；每餐水果拳頭大；菜比水果多一點；飯跟蔬菜一樣多；豆魚蛋肉一掌心；堅果種子一茶匙。全穀雜糧至少1/3未精製也是每日飲食指南重點。",solve:"1錯在只寫『每天早上』一杯奶，應早晚；2水果拳頭大正確；3『蔬菜1/2深色』不是我的餐盤六句核心且題源不採；4至少1/3全穀未精製正確。因此24，選D。",options:["A 1錯、3不採。","B 3不採。","C 1錯。","D 正確，2與4。"],memory:"餐盤：水果拳頭；全穀至少1/3未精製；奶是早晚各一杯。"},
"H109_86731_09":{teach:"古柯鹼會阻斷單胺神經傳導物質（尤其多巴胺、正腎上腺素等）再吸收，造成強烈欣快、警覺、心跳與血壓上升等刺激作用，因此分類為中樞神經興奮劑。",solve:"所以選C。",options:["A 不是主要以麻醉藥品分類的考點，雖局部麻醉用途存在。","B 不是典型迷幻劑。","C 正確，中樞神經興奮劑。","D 與實際藥理方向相反。"],memory:"古柯鹼＝中樞興奮；K他命／鎮靜安眠類才偏抑制。"},
"H109_86731_10":{teach:"緊急醫療救護系統包含現場急救、到院前救護與運送。心跳呼吸停止是時間敏感急症，非創傷性心跳停止需優先現場高品質CPR與AED，再配合運送，而不是一開始就只顧搬上車。一般民眾做的是急救（first aid／BLS），不是完整『現場醫療處置』。",solve:"1撥119／112啟動EMS正確；3非創傷心跳停止強調就地CPR與穩定正確；2否認送醫途中救護錯；4把一般民眾描述成做『醫療處理』不精確。因此選A＝13。",options:["A 正確，1、3。","B 含2錯。","C 含4錯。","D 2、4皆錯。"],memory:"OHCA核心：先啟動EMS＋現場CPR/AED；到院前救護也屬EMS。"},
"H109_86731_11":{teach:"心跳停止後每延遲1分鐘沒有CPR與去顫，存活機率會快速下降。傳統急救教材常用『每分鐘下降約7–10%』作記憶數字，因此旁觀者立即CPR與快速AED非常重要。",solve:"依題源統計數字選B 7–10%。",options:["A 3–6%低於題源常用值。","B 正確，約7–10%／分鐘。","C 12–15%過高。","D 20%過高。"],memory:"OHCA每拖1分鐘，存活率約掉7–10%；所以CPR/AED不能等。"},
"H109_86731_12":{teach:"長照2.0服務包括照顧與專業服務、交通接送、輔具與居家無障礙、喘息、餐飲等多元支持。『居家健康檢查』不是長照2.0標準服務項目名稱；一般預防保健／健檢屬其他醫療與公衛體系。",solve:"C不屬長照2.0標準服務項目，因此選C。",options:["A 是長照常見服務。","B 是服務之一。","C 不是標準長照服務項目，故為答案。","D 喘息服務是支持家庭照顧者的重要項目。"],memory:"長照是『照顧、復能、交通、輔具、喘息、餐食』，不是把一般健檢都包進去。"},
"H109_86731_13":{teach:"舊稱『精神官能症』多指焦慮、恐懼、強迫、身心症等神經症性問題，通常保有病識感與現實感，主要困擾在情緒與焦慮。妄想、幻覺則屬精神病性症狀，較典型見於思覺失調症、重度情緒障礙合併精神病等。",solve:"B說精神官能症有時會出現妄想、幻聽，與『保有現實感』的典型定義衝突，因此不正確。",options:["A 正確方向。常以焦慮、情緒與身體症狀表現。","B 錯，故為答案。妄想／幻覺屬精神病性症狀。","C 正確。典型上有病識感。","D 正確。現實檢驗多維持。"],memory:"官能症（舊稱）＝有病識感、現實感；妄想幻覺＝想到精神病性症狀。"},
"H109_86731_14":{teach:"『Teens’幸福9號』是青少年親善生育保健／醫療服務概念，強調友善、隱私、性與生殖健康諮詢，也協助青少年與家長／法定代理人溝通。它是政府／醫療體系推動的青少年友善服務，不是由勵馨基金會設立。",solve:"A錯誤，所以選A。B、C、D都符合青少年親善服務精神。",options:["A 錯，故為答案。不是由勵馨基金會設立。","B 正確。提供青少年生育與保健相關服務。","C 正確。可協助親子／法定代理人溝通。","D 正確。隱私與友善是重要原則。"],memory:"Teens幸福9號＝青少年友善生殖健康醫療，不是特定民間基金會專案。"},
"H109_86731_15":{teach:"積極同意（affirmative consent）核心是『只有明確、自願、持續、具能力的同意才算同意』。沒有拒絕不等於同意；醉酒、失去判斷能力、昏睡或受脅迫時不能形成有效同意；同意也可隨時撤回。未達法定年齡或欠缺意思能力者受特別法律保護。",solve:"C說飲酒後只要還能口頭同意就一定不算性侵，忽略醉酒程度可能使人無法有效同意，因此錯。",options:["A 正確。主動者有責任確認對方明確同意。","B 正確方向。有效同意需具充分清醒與決策能力。","C 錯，故為答案。酒後是否能有效同意要看判斷能力，不能只靠一句口頭『好』。","D 正確方向。未達法定年齡／欠缺意思能力者的同意受限制。"],memory:"積極同意：明確、自願、清醒、持續、可撤回；沉默／醉酒不是自動同意。"},
"H109_86731_16":{teach:"成人心跳停止生存之鏈舊版五環依序：1立即辨識心跳停止並啟動EMS→3盡早高品質CPR→4快速去顫→2有效高級救命術→5整合心臟停止後照護。邏輯就是『認出→壓→電→進階→後照護』。",solve:"順序13425，因此選C。",options:["A 把ALS放在CPR與去顫之前。","B 一開始就去顫，少了辨識與啟動系統。","C 正確，13425。","D 把CPR放在辨識啟動前。"],memory:"生存鏈：認、壓、電、進階、後照護。"},
"H109_86731_17":{teach:"AED傳統中文口訣『開、貼、讀、電』：打開AED／電源→貼電極片→讓AED讀取／分析心律（所有人離開）→若建議電擊則確認離開後按電擊鍵。",solve:"選B開貼讀電壓。",options:["A 先讀再貼無法分析。","B 正確。開→貼→讀→電。","C 應先開機取得語音指示。","D 未貼片就不能分析。"],memory:"AED四字：開、貼、讀、電。"},
"H109_86731_18":{teach:"代謝症候群五指標之一是『HDL偏低』，不是偏高。男性HDL<40 mg/dL、女性<50 mg/dL才算風險指標；HDL較高通常是保護性。其他常見門檻包括空腹血糖≥100、血壓≥130/85、男性腰圍≥90。",solve:"B寫『男性HDL≥40』作為指標，方向相反，所以不是代謝症候群風險指標。",options:["A 是指標門檻。","B 不是，故為答案；應是男性HDL<40。","C 是指標門檻。","D 是指標門檻。"],memory:"HDL是『好膽固醇』：代謝症候群看太低，不是太高。"},
"H109_86731_19":{teach:"腹膜炎是腹膜受到感染或刺激後的急症，典型可出現劇烈持續腹痛、壓痛／反彈痛、腹壁僵硬（板狀腹）、發燒、噁心、食慾差。闌尾炎若穿孔也可進展成腹膜炎。題幹的『觸碰更痛＋腹部僵硬』是關鍵。",solve:"最符合C腹膜炎。",options:["A 腸炎多以腹瀉、絞痛為主，較少板狀腹。","B 闌尾炎常先臍周後右下腹痛，可能導致腹膜炎，但題幹已呈瀰漫腹膜刺激徵象。","C 正確。劇痛、壓痛、腹壁僵硬是腹膜炎警訊。","D 膀胱炎以頻尿、尿急、排尿痛為主。"],memory:"劇烈腹痛＋腹壁僵硬／反彈痛＝先想到腹膜炎、急腹症。"},
"H109_86731_20":{teach:"大量傷患初步檢傷優先處理立即威脅生命且可介入者。持續胸痛可能代表心肌缺血、胸腔損傷或其他危及生命問題；昏睡但生命徵象穩定、四肢外傷、歇斯底里但可大叫者雖仍需處理，若呼吸循環穩定優先度可稍後。",solve:"四人中阿三持續胸痛最可能有立即危及生命的胸腔／心血管問題，因此先救D。",options:["A 昏睡需評估，但題幹明示生命徵象穩定。","B 大面積四肢外傷若無大量出血／休克，優先度低於疑胸腔急症。","C 能大聲喊痛代表氣道與呼吸尚在，且題幹無生命徵象危急。","D 正確。持續性胸痛需優先排除危及生命狀況。"],memory:"檢傷先ABC／立即生命威脅；能大聲喊不等於最危急，胸痛可能藏致命問題。"}
});

/* deep_batch_110_99890.js */
window.ITEM_DEEP=Object.assign(window.ITEM_DEEP||{}, {
"H110_99890_01":{teach:"癌症篩檢的年齡與頻率屬時效政策。110年題源當時，大腸癌公費糞便潛血篩檢對象並非『50–74歲一般民眾』這個精確組合；乳房攝影、口腔黏膜、子宮頸抹片則各有當時資格。考現行教甄必須改查最新國健署五癌篩檢資格。",solve:"原題答案A，表示A的年齡範圍／條件與110年公費規定不符。這類題不要只背舊數字，要先圈出『年度』。",options:["A 錯，故為答案。110年題源當時大腸癌篩檢資格並非此寫法。","B 依110年題源乳癌公費攝影資格可接受。","C 依題源當時口腔癌高風險篩檢規定可接受。","D 依題源當時子宮頸抹片政策可接受。"],memory:"癌篩年齡＝高時效。原題只用來練『查政策』，現行資格請看最新國健署。"},
"H110_99890_02":{teach:"成人燒傷九分法：頭頸9%、每側上肢9%、前軀幹18%、後軀幹18%、每側下肢18%、會陰1%。若只燒到某區域的一半，就取該區比例的一半。題目『前胸部』通常指前軀幹上半（胸部）約9%；右大腿正面是單側下肢的四分之一體表面積概念：單側下肢18%，前側9%，其中大腿約一半即4.5%；會陰1%。",solve:"前胸9%＋右大腿正面約4.5%＋會陰1%=14.5%，最接近14–15%，選B。",options:["A 9–10%只接近前胸，漏算大腿與會陰。","B 正確。9＋4.5＋1＝14.5%。","C 19–20%通常是把右大腿正面錯算成整個單側下肢的一半以上。","D 25–26%明顯過度估計。"],memory:"九分法進階：前胸9、前腹9；單腿18＝前9＋後9；單大腿前面約4.5；會陰1。"},
"H110_99890_03":{teach:"HIV主要攻擊CD4 T淋巴球，不是B淋巴球。感染後有『空窗期』：已感染、具傳染力，但檢驗可能尚未呈陽性；之後可進入長期無明顯症狀期，此時檢驗通常可呈陽性，稱HIV感染者。空窗期長短會因檢驗技術而異，舊教材常寫6–12週。",solve:"1錯（應為CD4 T細胞）；2依題源可接受；3正確，空窗期仍可傳染；4正確。故選D＝234。",options:["A 含1錯。","B 含1錯。","C 含1錯且漏3。","D 正確，234。"],memory:"HIV：攻擊CD4 T細胞；空窗期『驗不一定驗得出，但仍會傳染』。"},
"H110_99890_04":{teach:"K他命在臺灣屬第三級毒品，具解離與中樞神經抑制／麻醉作用。濫用可造成認知記憶受損、幻覺、意識改變；長期大量使用最具代表性的危害是K他命膀胱病變、頻尿、血尿、膀胱容量縮小，嚴重可造成不可逆泌尿道損傷。",solve:"B說泌尿傷害只是短暫、戒除就一定恢復，過度樂觀且錯誤，因此選B。",options:["A 正確。K他命為第三級毒品。","B 錯，故為答案。泌尿系統損害可能嚴重、持續甚至不可逆。","C 正確方向。濫用可影響記憶與認知。","D 正確。Ketamine具中樞神經抑制／解離麻醉特性。"],memory:"K他命三級；最具代表性長期傷害＝膀胱／泌尿道。"},
"H110_99890_05":{teach:"睪丸自我檢查若要做，最好在溫水淋浴『後』，此時陰囊皮膚放鬆，較容易觸摸睪丸與副睪。注意無痛硬塊、大小／形狀變化、沉重感等異常；任何異常應就醫，而不是自行診斷。",solve:"B說在溫水淋浴『前』因陰囊放鬆，時序相反，所以錯。",options:["A 題源視為正確，規律留意變化有助及早發現異常。","B 錯，故為答案。應在溫水浴後較放鬆時檢查。","C 正確。無痛腫塊、形狀改變、沉重感是警訊。","D 題源採較廣的男性生殖器自我觀察範圍。"],memory:"睪丸自檢關鍵：溫水『浴後』、陰囊放鬆、摸無痛硬塊。"},
"H110_99890_06":{teach:"臺灣AQI使用SO₂、NO₂、CO、O₃、PM₂.₅、PM₁₀六類污染物的副指標。NO（一氧化氮）不是直接列入AQI六項；AQI用的是NO₂（二氧化氮）。",solve:"A NO不在AQI標準六項，因此選A。",options:["A 不包含，故為答案；標準項目是NO₂。","B CO包含。","C O₃包含。","D PM2.5包含。"],memory:"AQI六項：SO₂、NO₂、CO、O₃、PM2.5、PM10；注意NO≠NO₂。"},
"H110_99890_07":{teach:"包裝食品強制標示通常包括品名、內容物、淨重、食品添加物、製造／國內負責廠商資訊、有效日期、營養標示等。『製造日期』並非所有一般包裝食品都必須強制標示的固定項目，法律重點是有效日期等法定資訊。",solve:"D製造日期不是此題法規要求的必標項目，因此選D。",options:["A 營養標示屬規範項目。","B 廠商名稱、電話、地址屬標示要求。","C 食品添加物需標示。","D 不是所有食品一律強制的法定基本項目，故為答案。"],memory:"食品標示常考陷阱：『有效日期』必標，不等於『製造日期』一律必標。"},
"H110_99890_09":{teach:"題組明美16歲、160 cm、62 kg。題源的熱量估算邏輯可用標準體重×活動熱量係數理解：標準體重約以BMI 22估算，22×1.6²≈56.3 kg；她放學後餐廳工作屬較有活動量，若採約33 kcal/kg，56.3×33≈1858 kcal，約1860 kcal。不同教材係數會有差異，這是題源計算法。",solve:"估算約1860 kcal，故選B。這題重點是先用標準體重而不是直接用62 kg，再乘活動係數。",options:["A 1660偏低。","B 正確，約1860 kcal。","C 2170較高。","D 2480高於題源估算。"],memory:"本題算法：標準體重≈22×身高²，再乘活動係數；56.3×33≈1860。"},
"H110_99890_10":{teach:"體重管理宜採小幅、可持續的能量赤字，而不是極端節食。題源對過重青少年採每日減少約300–500 kcal作為安全、漸進策略，同時維持均衡營養與活動；青少年仍在生長，更不宜大幅削減。",solve:"因此選D『可減少300–500大卡』。",options:["A 維持不變不利於題源減重目標。","B 增加300–500會增加能量盈餘。","C 減少1000–1200過度激烈，尤其對青少年不宜。","D 正確，題源採溫和赤字300–500 kcal。"],memory:"青少年體重管理：小幅調整，不做1000 kcal級的暴砍。"},
"H110_99890_11":{teach:"健康自主管理步驟要有因果順序：先選出想改善的具體習慣，再訂可衡量目標，接著擬執行計畫與獎勵，之後簽訂契約／承諾，最後執行並記錄。",solve:"3選習慣→1定目標→2擬計畫→4簽契約→5執行，故選B 31245。",options:["A 先定目標再選要改的習慣，順序不自然。","B 正確，31245。","C 把計畫放到目標之前。","D 從契約開始，缺乏前置目標與計畫。"],memory:"自主管理：選習慣→定目標→擬計畫→簽契約→執行記錄。"},
"H110_99890_12":{teach:"題源教材給成人／一般減重飲食的最低熱量概念為每日不低於1200 kcal，以避免營養不足與過度節食。不過青少年、孕婦、慢性病患等應個別評估，1200不是所有人通用的醫療安全下限。",solve:"依原題答案，最低為1200 kcal，選A。",options:["A 正確，原題教材門檻1200 kcal。","B 1400不是題源答案。","C 1500不是。","D 1600不是。"],memory:"本題教材數字＝1200 kcal；真實減重熱量仍需依年齡、性別、體位與活動個別評估。"},
"H110_99890_13":{teach:"陪伴憂鬱症患者的核心是『傾聽、接納、陪伴、鼓勵專業求助』，而不是叫對方振作或把症狀視為意志薄弱。不要責備；即使對方拒絕好意也可保持耐心；面對沮喪先同理，不急著爭辯或否定感受。",solve:"1『叫他多加油』可能造成壓力與否定感；2、3、4較合適，所以選D＝234。",options:["A 含1錯。","B 含1錯。","C 含1錯且漏3。","D 正確，234。"],memory:"憂鬱陪伴三不：不責備、不說『想開點／加油』、不急著反駁；做傾聽與轉介。"},
"H110_99890_14":{teach:"產前診斷工具各有用途：超音波看胎兒結構與胎盤；羊膜穿刺取得羊水與胎兒細胞，可做染色體／基因分析，羊水AFP等可評估神經管缺損；絨毛取樣約10–13週取得少量絨毛組織做染色體／基因；臍帶血採樣可在較後孕期評估血液／染色體等。",solve:"C把絨毛取樣量寫成『10–15公克』，實際取得的是非常少量組織，不可能以十幾公克計，因此錯。原題答案C。",options:["A 正確。超音波可評估位置與結構。","B 題源視為可接受，羊水檢查可協助染色體與神經管缺損評估。","C 錯，故為答案。絨毛取樣量級不可能是10–15公克；此處單位／數值錯誤。","D 大方向正確。臍血可作胎兒血液與遺傳相關檢查。"],memory:"絨毛取樣是『少量組織』，看到10–15公克要警覺單位離譜。"},
"H110_99890_15":{teach:"性自主法規要精準看年齡。刑法對未滿14歲與14歲以上未滿16歲者有不同保護規定，不是一路延伸到未滿18歲都用同一性交罪。另成年人帶走未成年少女可能涉及略誘等罪，且民事責任與法定代理人責任依當時成年年齡與具體情形判斷。",solve:"B說『14歲以上未滿18歲性交皆處7年以下』，把刑法年齡上限從16歲錯延伸到18歲，所以為錯誤。",options:["A 依題源當時刑法，與未滿14歲性交有較重刑責。","B 錯，故為答案。保護性同意年齡的刑法切點是未滿16歲，不是未滿18歲一律同罪。","C 依個案帶離未成年人情形可能涉及略誘，需看具體構成。","D 屬當時民法成年與監護責任脈絡的題源判斷，現行成年年齡已調整，屬時效法規。"],memory:"性自主刑法先圈年齡：<14、14–<16是重要切點；18歲不是性交罪同一門檻。"},
"H110_99890_16":{teach:"老年性聽力損失（presbycusis）典型先影響高頻聲音，特別是子音辨識，因此老人可能『聽得到有人說話，但聽不清楚內容』，在吵雜環境更明顯，之後才逐漸波及較低頻。",solve:"所以選A高頻率聲音。",options:["A 正確。老年性聽損通常從高頻開始。","B 低頻通常較晚受影響。","C 不是最早典型。","D 並非所有頻率一開始都無法辨認。"],memory:"老年性聽損：先掉高頻，先聽不清子音。"},
"H110_99890_17":{teach:"青少年打工安全要查公司是否合法、是否提供職安教育訓練、看清勞動契約與工作內容。高薪免經驗可能是詐騙警訊；學生平安保險不能取代依法應有的勞工／職災保障；個人防護具原則上應由雇主依工作危害提供與管理，不應要求學生自行負擔完整設備。",solve:"2查立案、5職安訓練、6契約內容正確，故選B＝256。",options:["A 含1高薪免經驗迷思、4防護具責任錯。","B 正確，256。","C 含3、4錯。","D 同樣含3、4錯。"],memory:"打工三查：公司是否合法、職安訓練有沒有、契約看清楚；PPE不是叫學生自備就算。"},
"H110_99890_18":{teach:"癲癇抽搐時最重要是保護安全：清除周圍尖銳／硬物、保護頭部、記錄時間；不要塞東西進嘴、不要強行搬動或壓制。抽搐結束後再視情況側臥維持呼吸道。",solve:"D『清除現場危險物品』最正確。A俯臥不適當；B塞湯匙危險；C不必要搬動患者。",options:["A 錯。發作中不需強轉俯臥，應就地保護。","B 錯。不可塞湯匙或任何物品入嘴。","C 錯。不因通風而任意搬動正在抽搐者。","D 正確。先清除周遭危險物避免二次傷害。"],memory:"癲癇發作：就地保護、清危險、計時間；不塞嘴、不硬搬、不壓制。"},
"H110_99890_19":{teach:"RU486藥物流產必須由醫師評估與處方，先用超音波確認子宮內孕並估孕週，服藥後需回診確認是否完全流產。不能自行藥房購買，也不能自行把同一療程隔週重複；適用孕週依核准規範，題源不採『12週內皆可』。",solve:"2確認宮內孕、3醫師處方、6回診追蹤正確，故選C＝236。",options:["A 含1『12週內皆適用』錯。","B 含4自行隔週再服錯。","C 正確，236。","D 含1、4錯。"],memory:"藥物流產三要：超音波確認、醫師處方、回診確認。"},
"H110_99890_20":{teach:"媒體健康訊息評估可分：先閱讀內容與呈現形式，解讀訊息明示／暗示的意涵，再思考它與自己的關係，接著查來源與證據、批判分析，最後形成自己的判斷。重點不是『先相信再查』，而是從訊息本身一路追到來源與證據。",solve:"題源正確順序為2→5→1→4→3→6，即閱讀→解讀→自我意義→查來源→批判→形成想法，選A。",options:["A 正確，251436。","B 一開始就批判但尚未完整閱讀／解讀來源。","C 順序把自我感受放太前，來源放太後。","D 查來源很重要，但題源流程不是由來源作第一步。"],memory:"媒體識讀：看內容→解讀暗示→想與我何干→查來源→批判證據→形成判斷。"}
});

/* deep_batch_111_107906.js */
window.ITEM_DEEP=Object.assign(window.ITEM_DEEP||{}, {
"H111_107906_01":{teach:"WHO已把Gaming disorder納入ICD-11。診斷核心不是『玩很久』，而是對遊戲失去控制、把遊戲置於其他生活活動之上，即使造成負面後果仍持續，並造成個人、家庭、社交、學業或職業功能顯著受損，典型需持續約12個月（嚴重時可縮短）。健保是否給付特定治療方案屬政策與醫療支付問題，不能把診斷存在直接等同健保給付。",solve:"A、C、D都符合ICD-11遊戲成癮概念；B把『治療一定屬健保給付』當一般事實，原題判為錯誤，因此選B。",options:["A 正確。WHO於ICD-11納入gaming disorder。","B 錯，故為答案。診斷被承認不代表所有治療方式都自動由健保給付；支付政策需另查。","C 正確。失去控制與遊戲優先於生活是核心症狀。","D 正確。需有顯著功能損害，通常症狀持續約12個月。"],memory:"遊戲成癮判斷三點：失控、優先、明知有害仍繼續＋功能受損。"},
"H111_107906_02":{teach:"口罩、快篩、耳溫槍等可能屬醫療器材，網路販售不是『一般商品想賣就賣』。業者需具合法醫療器材商／藥商資格，並依規定登記通路與相關資訊；只有法規開放可網路販售的品項才能在線上販售。私人轉售、交換也可能涉及法規。",solve:"A完整描述合法網售醫療器材所需資格與通路登記，因此正確。B、C、D都錯把價格低或私人轉讓當成不受管制。",options:["A 正確。網售醫材需依法取得資格並符合通路與品項規範。","B 錯。是否受管制與單價無關。","C 錯。防疫趨勢改變不代表醫療器材可任意拍賣。","D 錯。交換／轉讓仍可能涉及醫療器材管理法規。"],memory:"醫療器材不是一般二手商品：先看『資格＋品項是否開放＋通路登記』。"},
"H111_107906_03":{teach:"COVID-19防疫可分個人防護、社區防疫、邊境檢疫等層級。洗手、口罩、避免摸眼口鼻首先是『個人防護行為』；社區防疫則更常指群聚管理、社區監測、隔離檢疫、公共衛生措施等。政策內容具有高度時效性。",solve:"原題問錯誤，答案B。其措施本身是正確防疫行為，但題源認為把它分類為『社區防疫』不精準，應歸個人防護。A、C、D依111年當時政策脈絡作為境外／邊境措施。",options:["A 依題源分類可視為境外阻絕措施。","B 為原題答案。洗手、戴口罩、少摸臉屬個人防護，不是題源所稱社區防疫層級。","C 依題源屬邊境檢疫／阻絕。","D 是限定111-04-21前後的歷史政策敘述，不能套用到現在。"],memory:"防疫分類題先分層：洗手口罩＝個人；檢疫＝邊境；群聚管理＝社區。"},
"H111_107906_04":{teach:"產後與嬰兒照護要以母嬰健康與法規倫理為優先，不應用促銷利益取代專業建議。母乳可提供營養與免疫成分，但嬰兒免疫不是『全靠初乳』；配方奶也不能因牛乳酪蛋白多就說更營養。醫療／保健用品與藥品、維生素的網路轉售或贈與亦有法規與安全問題。",solve:"題目列的1–6都各有不恰當之處，因此選D 123456。",options:["A 只列3–6，漏掉1、2的不恰當。","B 只列4–6，漏更多。","C 只列1–3，漏掉網路轉售／贈與相關風險。","D 正確。六項皆不宜直接這樣做。"],memory:"母嬰題先問：有沒有把『健康安全』讓位給促銷／迷思／網路轉售？有就警覺。"},
"H111_107906_05":{teach:"《跟蹤騷擾防制法》針對反覆或持續、違反意願、與性或性別有關，且使人心生畏怖並影響生活的跟騷行為，列有監視、守候、尾隨等樣態。現有或曾有親密關係者之相關行為，與《家庭暴力防治法》等制度可能產生適用分工；題源把未同居伴侶的親密關係跟騷排除在本法此題範疇。",solve:"依111年原題答案，C不是此題所問《跟蹤騷擾防制法》範疇；A、B、D皆符合題源對跟騷行為與制度的描述。",options:["A 符合跟騷法核心構成要件。","B 可能屬反覆／持續、違反意願的追求與騷擾樣態。","C 為原題答案；親密關係案件涉及家暴法等特別規範，題源不納入此處。","D 題源視為正確，涉及法定跟騷樣態與預防性羈押機制。"],memory:"跟騷法題先看『反覆持續＋違反意願＋性／性別＋畏怖影響生活』，親密關係另注意家暴法分工。"},
"H111_107906_06":{teach:"健康體適能常包含心肺適能、肌肉適能、柔軟度、身體組成。『柔軟度』才是關節可活動範圍與周圍肌肉、韌帶延展能力；『肌肉適能』包含肌力與肌耐力。",solve:"B把柔軟度定義錯套成肌肉適能，所以是錯誤。",options:["A 正確。健康體適能強調能應付日常與休閒而不過度疲勞。","B 錯，故為答案。這是柔軟度定義。","C 正確。肌力是一回最大收縮力量。","D 大方向正確。良好心肺適能與心血管健康高度相關。"],memory:"關節活動範圍＝柔軟度；一次最大力＝肌力；持續反覆＝肌耐力。"},
"H111_107906_07":{teach:"代謝症候群五指標：腰圍、血壓、空腹血糖、TG、HDL。男性腰圍≥90、血壓≥130/85、空腹血糖≥100、TG≥150、HDL<40常作判定門檻。總膽固醇、BUN、GOT都不屬五項。",solve:"林先生：腰圍88未達；血糖150達；HDL42未低於40；血壓130/88達；TG120未達。共2項，所以選A。",options:["A 正確，共血糖、血壓2項。","B 3項通常是誤把其他檢驗或邊界值算入。","C 4項錯。","D 5項錯；五指標並非全部異常。"],memory:"代謝五項只算腰、壓、糖、TG、HDL；總膽固醇／肝腎功能不算。"},
"H111_107906_09":{teach:"癲癇發作是腦部異常電氣活動。急救目標是保護安全與呼吸道：移開危險物、保護頭部、記錄時間、抽搐後側臥；不要強塞物品進嘴、不要壓制肢體。失神發作可能只有短暫發呆；全身性強直陣攣發作可伴叫聲與抽搐。是否立即叫救護車要看首次發作、持續≥5分鐘、反覆發作未恢復、受傷等。",solve:"2、4、5是正確描述；3塞壓舌板錯；1『一律立即』過度概括，因此原題選C＝245。",options:["A 含1、3，兩者有問題。","B 含1，且漏掉3? 原題不採。","C 正確。2、4、5符合癲癇與急救原則。","D 含3『強塞物品』明顯錯。"],memory:"癲癇不塞嘴、不壓四肢；保護、計時、側臥。救護車看5分鐘／首次／受傷等警訊。"},
"H111_107906_10":{teach:"健康減重不是靠低營養密度或極端高蛋白斷澱粉。有效策略包括高纖全穀蔬果、減少含糖飲料、控制總熱量並規律活動。營養密度高代表同樣熱量能提供更多必要營養素，反而更適合體重管理。",solve:"2高纖全穀、4每天運動至少30分鐘、5不喝含糖飲料正確；1、3錯，所以選D＝245。",options:["A 含1錯。","B 含1、3錯。","C 含1、3且漏2、4。","D 正確。2、4、5是合理策略。"],memory:"減重三柱：高營養密度／高纖、少糖飲、規律動；別斷整類食物。"},
"H111_107906_11":{teach:"這是111年公費預防保健政策題。46歲女性可符合當時子宮頸癌與乳癌篩檢年齡；有嚼檳榔史者也可能符合口腔黏膜檢查資格。肝癌不是一般公費『癌症篩檢』項目；大腸癌當時年齡門檻較高。政策年齡已多次調整，現行需查最新國健署。",solve:"依題源情境可建議1子宮頸、2乳癌、3口腔癌，因此選A＝123。",options:["A 正確，符合題源當時資格。","B 含4肝癌，不屬一般公費癌篩。","C 含4、5且漏1、2。","D 含5在題源當時46歲尚未符合年齡門檻。"],memory:"癌篩資格是時效題；本題111年46歲＋檳榔史＝子宮頸、乳、口腔。"},
"H111_107906_12":{teach:"清醒嬰兒嚴重異物哽塞：以手支撐頭頸、頭低於胸，做5次背部拍擊；翻成仰臥仍維持頭低於軀幹，做5次胸部推壓。每輪後只移除『看得見』的異物，不能盲目掏。",solve:"C錯在翻成仰臥後說『頭比軀幹高』；應繼續保持頭較低，利用重力協助排出，因此選C。",options:["A 正確。頭低於軀幹約一定角度。","B 正確。兩肩胛骨間5次背拍。","C 錯，故為答案。仰臥胸推時仍應頭低於軀幹。","D 正確。只取出明顯可見異物，避免盲掏推更深。"],memory:"嬰兒哽塞：頭低＋5背拍＋翻身頭仍低＋5胸推。"},
"H111_107906_13":{teach:"消費者保護『三不』題源口訣為：危險公共場所不去、問題食品藥品不吃、標示不全商品不買。名人代言與誇大廣告雖需批判，但不是此『三不』固定三項。",solve:"1、3、4正確，所以選D＝134。",options:["A 124把『不聽名人代言』納入固定三不，錯。","B 234同樣含2且漏1。","C 123含2且漏4。","D 正確：不去、不吃、不買。"],memory:"消費三不：危險場所不去、問題食藥不吃、標示不全不買。"},
"H111_107906_14":{teach:"長照2.0服務資格依年齡與身分類別判定。題源當時常見對象包含65歲以上失能老人、55歲以上失能原住民、50歲以上失智者、失能身心障礙者等。50歲原住民即使失能，仍未達『55歲以上失能原住民』門檻。",solve:"A的阿南只有50歲，依題源資格無法以『失能原住民』類別申請，因此選A。",options:["A 正確答案。50歲未達題源失能原住民55歲門檻。","B 68歲失能符合65歲以上失能老人。","C 失能身心障礙者屬服務對象。","D 50歲以上失智者符合題源資格。"],memory:"長照2.0舊門檻常考：65失能、55失能原住民、50失智、身障失能。"},
"H111_107906_15":{teach:"《傳染病防治法》將法定傳染病分級時，核心考量是疾病的致死／嚴重性、發生情形與傳播速度等公共衛生危害。『盛行率』是描述現有病例負擔的流行病學指標，但不是此題法條列出的分類考量。",solve:"依原題答案，A致死率、C發生率、D傳播速度均列入，B盛行率不列，因此選ACD。",options:["A 正確。致死率反映危害嚴重程度。","B 不選。盛行率不是此題法條列舉的分級因素。","C 正確。發生率反映新發疾病情形。","D 正確。傳播速度影響公共衛生風險。"],memory:"法定傳染病分級考量：死得多不多、發生多不多、傳得快不快。"},
"H111_107906_16":{teach:"盛行率表示某族群在特定時間點／期間已有疾病的人所占比例。表格若按65–69、70–74、75–79、80–84、85+呈現，可比較年齡層盛行率高低，但不能由盛行率直接推論『病情嚴重度』；也不能只看幾個點就宣稱每5歲都固定倍增。",solve:"依題源表格可得B年齡愈大盛行率愈高；C 85歲以上每百人約22位以上失智。A把盛行率誤當嚴重度；D『每5歲倍增』過度規律化。因此答案BC。",options:["A 錯。盛行率高不等於個別患者病情更嚴重。","B 正確。表格顯示年齡愈大盛行率上升。","C 正確。85歲以上盛行率約22%以上，可轉成每百人22人以上。","D 錯。資料上升不代表每5歲固定倍增。"],memory:"盛行率只能告訴你『有多少人有病』，不能直接說『病得多嚴重』。"},
"H111_107906_17":{teach:"憂鬱症是多因素疾病，不是單一個性或意志薄弱造成。風險可來自遺傳與生物易感性、重大壓力與創傷、負向認知／低自尊等心理因素，以及癌症、慢性疼痛、內分泌疾病等嚴重身體疾病與治療。",solve:"A、B、C、D都可能與憂鬱症發生相關，因此全選ABCD。",options:["A 正確。家族史與遺傳易感性會增加風險。","B 正確。壓力與創傷是重要觸發／風險因素。","C 正確。持續負向思考與低自尊可參與心理機制。","D 正確。重大身體疾病可提高憂鬱風險。"],memory:"憂鬱症用『生物＋心理＋社會』三面向理解，不怪單一原因。"},
"H111_107906_18":{teach:"『土壤碳匯／種碳』概念是利用土壤與植物把大氣中的碳固定、儲存在生物量與土壤有機質中。土壤是全球重要碳庫；種植與改善土壤管理可增加碳固定；經合格量測、驗證的增匯／減排有機會形成碳權。不是讓一般民眾把自己排放的CO₂直接灌進土裡。",solve:"A土壤為重要碳庫、C居家植栽可作日常增綠概念、D碳匯可連結碳權機制；B錯。因此原題選ACD。",options:["A 正確。土壤儲存大量有機碳。","B 錯。一般『種碳』不是把二氧化碳直接打入土壤。","C 題源視為正確，種植植物可增加碳固定與綠化。","D 正確方向。符合方法學、量測與驗證的碳匯可進入碳權機制。"],memory:"種碳＝讓植物／土壤『固定與儲存』碳，不是把CO₂直接埋地下。"}
});

/* deep_batch_111_109921.js */
window.ITEM_DEEP=Object.assign(window.ITEM_DEEP||{}, {
"H111_109921_01":{teach:"臺灣成人BMI分類與WHO國際標準不同。國健署常用：BMI<18.5過輕；18.5–24正常；24≤BMI<27過重；BMI≥27肥胖，肥胖再分級。",solve:"題目問我國定義，A完整符合24與27兩個切點，因此選A。",options:["A 正確。過重24≤BMI<27；肥胖≥27。","B 是常見WHO國際切點25／30，不是臺灣成人標準。","C 把切點設太低。","D 過重下限22.5錯。","E 切點錯誤。"],memory:"臺灣成人BMI：24過重、27肥胖。"},
"H111_109921_02":{teach:"每日飲食指南的三大產能營養素比例，題源採蛋白質10–20%、脂質20–30%、醣類50–60%總熱量。比例的目的在兼顧蛋白質需求、必需脂肪酸與碳水供能。",solve:"只有A依序符合蛋白質、脂質、醣類的建議範圍。",options:["A 正確：10–20%、20–30%、50–60%。","B 醣類太低且蛋白脂肪偏高。","C 把三者順序錯置。","D 順序錯置。","E 題源不採此範圍。"],memory:"三大營養素比例順口：蛋10–20、脂20–30、醣50–60。"},
"H111_109921_03":{teach:"正確量腰圍不是找肚臍，也不是直接貼肋骨或腸骨邊。國健署常用方法：站立自然呼吸，在最後一根肋骨下緣與腸骨上緣之中點，水平繞一圈，於吐氣末量測。",solve:"E描述左右腸骨上緣與肋骨下緣中間點，最符合標準，因此選E。",options:["A 肚臍位置因人而異，不是標準解剖定位。","B 腹部最高處不固定。","C 直接貼腸骨上緣不是中點。","D 直接貼肋骨下緣不是中點。","E 正確。肋骨下緣與腸骨上緣中點水平量。"],memory:"腰圍位置：『最下肋骨與腸骨上緣的中點』，不是肚臍。"},
"H111_109921_04":{teach:"巨量營養素（macronutrients）與微量營養素（micronutrients）的『巨／微』主要依人體每日需要量區分，不是分子量或食物中濃度。碳水、脂肪、蛋白質需求量大；維生素、礦物質通常需求量小。",solve:"區別根據是人體需求量，因此選A。",options:["A 正確。看人體所需量級。","B 食物中含量會因食品而異，不能用來定義。","C 與分子量無關。","D 不是單顆分子的重量。","E 因A正確，不能選。"],memory:"巨量／微量＝『人體要多少』，不是分子多大。"},
"H111_109921_05":{teach:"新版每日飲食指南六大類為：全穀雜糧類、豆魚蛋肉類、乳品類、蔬菜類、水果類、油脂與堅果種子類。舊稱『五穀根莖類』已改為『全穀雜糧類』，題目就是考新舊名稱。",solve:"E『五穀根莖類』不是現行六大類正式名稱，因此選E。",options:["A 是六大類。","B 是六大類。","C 是六大類。","D 是六大類。","E 不是現行正式名稱，故為答案；應稱全穀雜糧類。"],memory:"舊『五穀根莖』→新『全穀雜糧』。"},
"H111_109921_06":{teach:"月經週期第一天就是月經出血第一天，到下一次月經前一天為一週期。卵泡期以雌激素逐漸上升為主，排卵前子宮頸黏液較稀、延展性增加；排卵後黃體形成，黃體素上升，形成較黏稠、不利精子通過的G型黏液。",solve:"C把『卵泡期』與『黃體素迅速分泌、G型黏液』配在一起，時序錯誤，所以選C。",options:["A 一般週期約21–35天，28±7天是常見教學概念。","B 經期約3–7天，題源3–6天可接受。","C 錯，故為答案。黃體素與G型黏液主要在排卵後黃體期。","D 正確。從本次第一天到下次前一天。","E 正確方向。黃體期通常約14天，相對固定。"],memory:"卵泡期看雌激素；排卵後黃體期看黃體素。"},
"H111_109921_07":{teach:"早產定義是妊娠未滿37週即出生，也就是37週0天以前（通常22或20週後到36週6天，依定義而異）。",solve:"問『小於幾週』為早產，答案37週，選D。",options:["A 34週太低，34–36週仍屬早產的一部分。","B 同理。","C 36週不是定義切點。","D 正確，<37週為早產。","E 38週太高，37週已不屬早產。"],memory:"早產切點：未滿37週。"},
"H111_109921_08":{teach:"出生體重分類：低出生體重（LBW）<2500 g；極低出生體重（VLBW）<1500 g；超低出生體重（ELBW）<1000 g。",solve:"極低出生體重的切點是1500公克，所以選B。",options:["A 1300雖屬極低，但不是定義切點。","B 正確，<1500 g。","C 1700是低出生體重但不達極低定義。","D 同理。","E 同理。"],memory:"2500低、1500極低、1000超低。"},
"H111_109921_09":{teach:"WHO與臺灣母乳哺育建議的核心是：出生後前6個月純母乳哺餵，約6個月起添加適當副食品，同時可持續哺乳到2歲或更久，依母嬰意願與狀況。",solve:"全母乳建議6個月，因此選B。",options:["A 4個月不足題源建議。","B 正確，前6個月純母乳。","C 7個月不是標準。","D 8個月不是。","E 12個月不是『純母乳』期間。"],memory:"母乳：前6月純母乳，6月後加副食品並可續餵。"},
"H111_109921_10":{teach:"111年題源所稱政府補助『四癌篩檢』為乳癌、大腸癌、口腔癌、子宮頸癌。肝癌沒有一般人口的同型態公費篩檢計畫，而是針對B/C肝等高風險族群追蹤。後來政策已擴充肺癌篩檢，故須注意年代。",solve:"A–D都是當時四癌；E肝癌不是，因此選E。",options:["A 屬當時四癌。","B 屬。","C 屬。","D 屬。","E 不屬，故為答案。"],memory:"111年舊題四癌＝乳、大腸、口腔、子宮頸；後續已新增肺癌政策。"},
"H111_109921_11":{teach:"長照服務依提供場域／方式，可概分居家式、社區式、機構住宿式，並包含家庭照顧者支持服務。『家庭共照式』不是《長期照顧服務法》標準服務方式名稱。",solve:"C不是法定標準分類，因此選C。",options:["A 屬居家式服務。","B 屬社區式服務。","C 不是標準分類，故為答案。","D 屬機構住宿式。","E 法規亦重視家庭照顧者支持。"],memory:"長照場域三類：居家、社區、住宿機構；另有照顧者支持。"},
"H111_109921_12":{teach:"職業災害包括因工作原因造成的疾病、傷害、失能或死亡，職業危害可分物理、化學、生物、人因、社會心理等。依勞工職災保險與相關規定，合理上下班途中發生事故在一定條件下也可能被認定為職業傷害。",solve:"D說上下班途中傷害一律不包括，錯誤，所以選D。",options:["A 大方向正確，職業病屬職業災害範疇。","B 正確。涵蓋疾病、傷害、失能、死亡。","C 正確。是常見危害分類。","D 錯，故為答案。通勤災害在符合法定條件時可列職業傷害。","E 正確。下背痛可與搬運、姿勢等人因危害相關。"],memory:"職災不要忘『通勤』：不是一律排除，要看法定合理途徑與條件。"},
"H111_109921_13":{teach:"身上著火的標準自救是Stop, Drop, Roll：停止跑動、躺下、翻滾；同時用手遮住臉部保護口鼻與臉。題源口訣排列為『摀臉、停、躺、滾』。跑動會增加氧氣與火勢。",solve:"依題源順序選D。",options:["A 題源將摀臉放最前。","B 先躺再停邏輯不通。","C 順序不符題源。","D 正確：摀臉、停、躺、滾。","E 順序錯亂。"],memory:"衣服著火：保護臉、停止跑、躺下、滾動。"},
"H111_109921_14":{teach:"滅火器P.A.S.S.操作：Pull拉開保險插梢、Aim瞄準火源底部、Squeeze壓下把手、Sweep左右掃射。中文口訣就是『拉、瞄、壓、掃』。",solve:"因此選B。",options:["A 把掃與壓顛倒。","B 正確，拉瞄壓掃。","C 順序錯。","D 順序錯。","E 順序錯。"],memory:"滅火器：拉、瞄、壓、掃（PASS）。"},
"H111_109921_15":{teach:"COVID-19疫苗平台要分清：AZ是非複製型腺病毒載體；BioNTech與Moderna是mRNA；Novavax是重組棘蛋白『蛋白質次單元』疫苗；高端也是蛋白質次單元。",solve:"C把Novavax誤寫成腺病毒載體，因此錯。",options:["A 正確，AZ是腺病毒載體。","B 正確，BNT是mRNA。","C 錯，故為答案。Novavax是蛋白質次單元疫苗。","D 正確，Moderna是mRNA。","E 正確，高端為重組棘蛋白次單元平台。"],memory:"AZ＝腺病毒；BNT/Moderna＝mRNA；Novavax/高端＝蛋白次單元。"},
"H111_109921_16":{teach:"COVID-19在臺灣法定傳染病分類曾隨疫情調整。111年『嚴重特殊傳染性肺炎』並非第一類法定傳染病，而是當時的第五類法定傳染病。病毒為SARS-CoV-2，屬冠狀病毒科β冠狀病毒，潛伏期常在1–14天內，兒童整體重症比例較成人低。",solve:"A說它屬第一類，錯誤，因此選A。其餘為當時教材常見敘述。",options:["A 錯，故為答案。當時列第五類，不是第一類。","B 正確方向。SARS-CoV-2屬β冠狀病毒。","C 符合早期疫情常用潛伏期描述。","D 大方向正確，兒童多數較輕但仍可能重症。","E 冠狀病毒宿主範圍廣；題源視為正確。"],memory:"法定分類是時效題：111年COVID-19＝第五類；後來又調整。"},
"H111_109921_17":{teach:"HPV非常常見，男女都可能感染；多數透過性接觸或親密皮膚黏膜接觸傳播。高風險型可造成子宮頸癌，也與陰莖癌、肛門癌、口咽癌等相關。男性風險並非『低很多』，因此也有接種疫苗與安全性行為的需要。",solve:"C以性別錯誤淡化男性HPV風險，因此為錯誤。",options:["A 正確。持續高風險HPV感染是子宮頸癌主因。","B 正確。性接觸是主要傳播途徑。","C 錯，故為答案。男性也常感染且會有癌症／疣風險。","D 正確。HPV與陰莖癌相關。","E 大方向正確。不同價數疫苗涵蓋型別不同，可預防相當比例相關感染／病變。"],memory:"HPV不是『女性疾病』：男女都感染、都可能得相關癌症、都可從疫苗受益。"},
"H111_109921_18":{teach:"WHO防治非傳染性疾病（NCDs）的四大可改變行為危險因素是：菸草使用、有害飲酒、不健康飲食、身體活動不足。『久坐』本身也是重要健康風險，但在經典四大行為危險因素清單中不獨立列為第五項。",solve:"A–D就是四大因素；E久坐不在經典四項，故選E。",options:["A 是四大之一。","B 是四大之一。","C 是四大之一。","D 是四大之一。","E 不是經典四大清單獨立項目，故為答案。"],memory:"NCD四大行為：菸、酒、不健康飲食、不運動。"},
"H111_109921_19":{teach:"《健康食品管理法》中的『健康食品』是法律名詞，須經審查／許可，才能以核准方式宣稱特定保健功效；本質仍是食品，不是藥品。沒有通過健康食品許可的普通食品，不能靠改名『保健食品』就合法宣稱保健功效。",solve:"B錯在以為未認證食品只要改稱保健食品就能宣稱部分功效，因此選B。",options:["A 正確。健康食品是法定名詞。","B 錯，故為答案。名稱不能繞過健康食品功效宣稱法規。","C 正確方向。核准健康食品可標示／廣告核准保健功效。","D 為題源當時核准功效項目數，屬時效資訊。","E 正確。健康食品不是治療疾病的藥品。"],memory:"『健康食品』有法定認證；『保健食品』不是拿來繞過認證的名稱。"},
"H111_109921_20":{teach:"糖尿病診斷常見標準之一：HbA1c≥6.5%（需使用標準化檢驗，無典型高血糖症狀時通常需複驗確認）。其他也包括空腹血糖≥126 mg/dL、OGTT 2小時≥200、或有典型症狀且隨機血糖≥200。4.5%屬正常低端，不是糖尿病門檻。",solve:"E把HbA1c診斷門檻寫成4.5%，明顯錯誤，因此選E。",options:["A 正確。三多是典型高血糖症狀。","B 正確。可體重減輕與疲倦。","C 正確。第一型、第二型為兩大主要類型。","D 大方向正確。妊娠糖尿病多在產後改善，但日後二型風險升高。","E 錯，故為答案。HbA1c診斷門檻是≥6.5%，不是4.5%。"],memory:"糖尿病HbA1c切點：6.5%。4.5%絕對不是。"},
"H111_109921_21":{teach:"臺灣AQI主要由SO₂、NO₂、CO、O₃、PM₂.₅、PM₁₀等污染物的副指標計算。題目中的SO3與CO2不是AQI標準六項。",solve:"3 SO₂、4 NO₂、5 CO、6 O₃、7 PM2.5、8 PM10，共345678，選B。",options:["A 含1 SO3與2 CO2，錯。","B 正確，345678。","C 含SO3、CO2且漏粒狀污染物。","D 漏O3、PM2.5等。","E 含CO2且漏多項。"],memory:"AQI六項：SO₂、NO₂、CO、O₃、PM2.5、PM10。"},
"H111_109921_22":{teach:"長照2.0社區整體照顧體系常用ABC三級：A社區整合型服務中心、B複合型服務中心、C巷弄長照站。題目把它編號為2、3、4。",solve:"因此正確組合234，選C。",options:["A 含國家級、居家照護站等非ABC三級名稱。","B 含1、漏4。","C 正確，2社區整合、3複合、4巷弄。","D 含5、漏2。","E 同樣含1。"],memory:"長照ABC：A社區整合、B複合、C巷弄長照站。"},
"H111_109921_23":{teach:"傳統火災分類：A類普通可燃物（木紙布）、B類易燃液體／油類、C類電氣、D類金屬。部分國家另有K/F類烹調油脂火災，但『E類爆炸火災』不是此題分類。",solve:"1–4正確，5錯，所以選B＝1234。",options:["A 多了5 E類爆炸火災。","B 正確，A/B/C/D四類。","C 漏D類金屬。","D 漏B且組合不全。","E 含5錯。"],memory:"火災A普通、B油、C電、D金屬；沒有『E爆炸』這個題源分類。"},
"H111_109921_24":{teach:"環境荷爾蒙（內分泌干擾物）可干擾荷爾蒙合成、作用或代謝。常見例子包括鄰苯二甲酸酯塑化劑、戴奧辛、DDT、多氯聯苯、雙酚A等。",solve:"1–5全部都是典型環境荷爾蒙例子，所以選D。",options:["A 只列3、4、5，漏1、2。","B 漏1、5。","C 只列1、5。","D 正確，12345全是。","E 漏2、4。"],memory:"環境荷爾蒙代表：塑化劑、戴奧辛、DDT、PCB、BPA。"},
"H111_109921_25":{teach:"避孕『正確使用成功率高』要分方法。口服避孕藥在正確使用下非常有效；保險套正確全程使用也可達高保護率；結紮屬高效長效方法。性交中斷、基礎體溫、安全期受人為與週期變異影響較大；緊急避孕應越早使用，不是固定等48小時後才開始。",solve:"2口服避孕藥、3保險套、6結紮符合題源『正確操作成功率>95%』，選C＝236。",options:["A 含7『48小時後才服』不合理。","B 含4、5自然避孕法，可靠度較低。","C 正確，236。","D 含4、5。","E 把低效方法全納入。"],memory:"高效避孕題先抓：口服藥、正確保險套、結紮；自然法／中斷較不可靠。"},
"H111_109921_26":{teach:"代謝症候群五項是：1腹部肥胖、3血壓偏高、4空腹血糖偏高、5三酸甘油酯偏高、6 HDL偏低。BMI與總膽固醇都不是五項診斷因子。符合≥3項即可。",solve:"正確編號13456，選A。",options:["A 正確，13456。","B 含2 BMI、漏1腰圍。","C 含7總膽固醇、漏6 HDL。","D 含2 BMI、漏6。","E 含2與7，且漏4、5。"],memory:"代謝五項：腰、壓、糖、TG、HDL；BMI、總膽固醇排除。"},
"H111_109921_27":{teach:"WHO健康促進學校經典六大範疇：學校衛生政策、學校物質環境、學校社會環境、社區關係、個人健康技能、健康服務。題目編號即1、2、3、6、7、8。",solve:"組合123678，選B。",options:["A 含4、5而漏1、2。","B 正確，123678。","C 把4、5納入並漏7、8。","D 含4、漏6。","E 缺1且含4、5。"],memory:"HPS六範疇：政策、物環、社環、社區、技能、健康服務。"},
"H111_109921_28":{teach:"HIV由人類免疫缺乏病毒引起，主要經性行為、血液、母子傳播；日常接觸唾液、汗水、共游泳池、蚊蟲叮咬不會傳播。至今仍無可常規預防HIV感染的疫苗，但有PrEP、保險套與U=U等有效策略。",solve:"1病毒致病、2無疫苗、5血液／體液交換可傳染正確；3、4、6、7都是常見迷思，所以選C＝125。",options:["A 把日常接觸與蚊蟲傳播都錯列。","B 含3、7錯。","C 正確，125。","D 含3錯。","E 含7錯。"],memory:"HIV三路：性、血、母子；不靠汗、唾液、游泳池、蚊子。"},
"H111_109921_29":{teach:"我的餐盤標準口訣：每天早晚一杯奶；每餐水果拳頭大；菜比水果多一點；飯跟蔬菜一樣多；豆魚蛋肉一掌心；堅果種子一茶匙。題目中的1、3、4、6正確；2把拳頭改成掌心，5把掌心改成拳頭。",solve:"正確組合1346，選B。",options:["A 2、5錯。","B 正確，1346。","C 漏1、3。","D 含2錯且漏4、6。","E 含2、5錯。"],memory:"餐盤手勢：水果『拳頭』、蛋白質『掌心』，最容易互換出題。"},
"H111_109921_30":{teach:"垃圾減量6R在題源版本包括Reduce減量、Reuse再使用、Recycle回收、Repair修理、Refuse拒絕、Recovery回收再生／資源回復。題目中的Recapture、Reanalysis不是標準6R。",solve:"對應編號2、3、4、5、6、8＝234568，選A。",options:["A 正確，234568。","B 含1 Recapture且漏4。","C 含7 Reanalysis且漏4。","D 含1且漏5。","E 含7且漏2。"],memory:"6R：Reduce、Reuse、Recycle、Repair、Refuse、Recovery。"}
});

/* deep_batch_112_114475.js */
window.ITEM_DEEP=Object.assign(window.ITEM_DEEP||{}, {
"H112_114475_01":{
  "teach":"性騷擾適用哪一部法律，先看『事件發生的關係與場域』。受僱者、求職者或具有實質工作／職場關係者遭受性騷擾，核心適用職場性騷擾規範；學生在校園內涉及校園性別事件則由性別平等教育法處理。校外實習雖然仍是學生身分，但若在實習工作場域受到該廠員工性騷擾，會涉及職場性騷擾法制。",
  "solve":"題幹強調『到工廠實習』『遭該廠員工性騷擾』，關鍵是實習中的工作關係，因此原題答案B。112年後法名已由《性別工作平等法》修正為《性別平等工作法》，備考現行法規時要用新名稱。",
  "options":["A錯：社會秩序維護法不是此類職場性騷擾事件的主要法源。","B對：依原題年度用語，實習職場中的性騷擾適用職場性別平等規範；現行法名為《性別平等工作法》。","C不是本題首要法源：雖然當事人是學生，但事件的直接行為人與場域屬實習工作場所。","D為一般性騷擾防制的補充法制，但有特別職場關係時通常優先適用職場性別平等法。"],
  "memory":"性騷擾先判場域：校園→性平教育；職場→性平工作；其他→性騷擾防制。"
},
"H112_114475_02":{
  "teach":"HIV預防要分三件事：U=U是感染者規律治療、病毒量持續測不到時，性傳播風險可降到實質為零；PrEP是暴露前預防用藥，需依醫囑規律服用，主要預防HIV，不能當成其他性傳染病疫苗；PEP是暴露後72小時內盡快開始、通常連續28天。PrEP和PEP都是藥物，不是疫苗。",
  "solve":"錯誤敘述是2、3、6：2把PrEP說成『事前24小時服藥即可絕對預防』，過度簡化且用了絕對化語言；3說PrEP也能預防其他性傳染病，錯；6說PrEP是疫苗，也錯。因此選A（236）。",
  "options":["A對：236正是三個錯誤敘述。","B含1，U=U核心概念本身正確，因此不選。","C含5；90-90-90屬原題年代政策進度，不是這組最明確錯項。","D含4，但PEP 72小時內啟動並服用28天是標準重點。"],
  "memory":"PrEP＝暴露前藥物；PEP＝72小時內、28天；兩者都不是疫苗，也不包治其他性病。"
},
"H112_114475_03":{
  "teach":"成人高品質CPR胸外按壓記住四個核心：速率100–120次／分、深度約5–6公分、每次完全回彈、盡量減少中斷且中斷最好少於10秒。『完全回彈』不是把手整個離開胸壁，而是解除壓力、不要倚靠胸口。",
  "solve":"1正確；2錯，成人深度不是『大於6公分』，過深會增加傷害；3正確；4錯，手可保持接觸胸壁，只要讓胸廓完全回彈即可。因此正確組合是1、3，選A。",
  "options":["A對：1、3皆符合高品質CPR。","B含4，錯在把完全回彈誤解成手必須離開胸壁。","C含2與4，兩項皆不正確。","D含4，因此不選。"],
  "memory":"CPR：100–120、5–6公分、全回彈、少中斷。"
},
"H112_114475_04":{
  "teach":"性別概念要分清：生理性別（sex）主要指生殖器官、染色體、荷爾蒙等生物特徵；性別認同是個人對自己性別的內在認同；社會性別（gender）則是社會文化對不同性別的角色、規範與期待；性傾向才涉及對何種性別產生情感或性吸引。",
  "solve":"C把社會性別定義為社會或群體對不同性別的標準與角色期待，正確。A把不同層面說成絕對關係，錯；B把LGBTQ+縮成只有同性戀；D把同性、異性、雙性戀這種性傾向概念誤當生理性別。",
  "options":["A錯：生理性別、性別認同與社會性別彼此相關但不是絕對一一對應。","B錯：LGBTQ+涵蓋多種性傾向與性別認同，不只同性戀。","C對：社會性別著重文化與社會角色期待。","D錯：同性戀、異性戀、雙性戀描述性傾向，不是生理性別。"],
  "memory":"sex看生物；gender看社會角色；identity看我是誰；orientation看我被誰吸引。"
},
"H112_114475_05":{
  "teach":"失智症不是正常老化，而是由多種腦部疾病造成的認知功能下降，且嚴重到影響日常生活。危險因子可分不可改變（年齡、遺傳等）與可改變（高血壓、糖尿病、抽菸、缺乏運動、社交孤立、憂鬱等）。女性整體失智盛行率通常不低於男性，尤其阿茲海默症更常見於女性。",
  "solve":"A同時犯兩個錯：把失智等同正常老化，且說男性更容易罹患。其餘B、C、D都屬已知可改變或相關危險因子，所以選A。",
  "options":["A錯：失智不是正常老化；整體而言女性並非比男性更少見。","B對：抽菸、睡眠與不健康飲食等生活型態會增加風險。","C對：社交孤立與認知退化／失智風險相關。","D對：三高與憂鬱都與較高失智風險相關。"],
  "memory":"失智≠正常老化；能改的風險先抓三高、菸、動少、孤立、憂鬱。"
},
"H112_114475_06":{
  "teach":"長照2.0服務對象的高頻門檻：65歲以上失能者；55歲以上失能原住民；50歲以上失智症者；失能身心障礙者等。題目年代的制度細節屬時效性資訊，但這幾個年齡門檻是常考配對。",
  "solve":"a 50歲失智可；e 65歲失能長者可。b只有50歲的失能原住民，未達55歲；c 55歲一般失能長者未達65歲；d失能身心障礙者的資格不能只靠題幹這個年齡敘述直接套入該組。因此原題選D（ae）。",
  "options":["A把b、c、d都納入，範圍過大。","B含c、d且漏e，不符。","C含d，但漏a。","D對：a與e符合原題採用的資格條件。"],
  "memory":"長照2.0常背：65失能、55原住民、50失智。"
},
"H112_114475_07":{
  "teach":"異物哽塞的腹部推擠（Heimlich）不適合所有人。嬰兒用背拍＋胸推；孕婦或明顯肥胖、無法環抱腹部者改用胸部推擠；若已失去意識則進入CPR流程，而不是站立式腹推。",
  "solve":"傑克BMI 40，屬明顯肥胖，腹部不易正確環抱與定位，因此適合胸壓／胸部推擠法，選C。",
  "options":["A 10個月嬰兒應用5次背拍＋5次胸推，不做成人胸部推擠。","B一般清醒成人若可環抱腹部，仍以腹部推擠為主。","C對：明顯肥胖者可改用胸部推擠。","D已昏迷，應啟動CPR與AED流程，不做站立胸推。","E一般體型成人並無改用胸推的必要。"],
  "memory":"哽塞：嬰兒背5胸5；成人腹推；孕婦／明顯肥胖改胸推；昏迷做CPR。"
},
"H112_114475_08":{
  "teach":"成癮可分耐受性、生理依賴／戒斷與心理依賴。心理依賴重點是『渴求、想再使用、覺得缺了它不行』；生理依賴則偏向停藥後出現身體或神經症狀；耐受性則是同樣效果需要越來越多劑量。",
  "solve":"C描述停止後若有所失、出現想再使用的衝動，正是心理渴求與心理依賴。A、D是戒斷／生理依賴；B是耐受性；E偏向藥物毒性或精神症狀。",
  "options":["A屬生理依賴與戒斷現象。","B屬耐受性：需要更多劑量才有原效果。","C對：渴求、衝動再用是心理依賴核心。","D是典型戒斷症狀。","E較像大量使用或停藥造成的精神症狀，不是心理依賴的定義。"],
  "memory":"耐受＝越用越多；戒斷＝停了身體難受；心理依賴＝一直想再用。"
},
"H112_114475_10":{
  "teach":"癌症公費篩檢題一定要看『題目年代』，因政策會更新。依112年前後原題條件：子宮頸抹片、乳房X光、口腔黏膜與大腸癌篩檢各有年齡／風險門檻；LDCT肺癌篩檢則針對特定年齡與重度吸菸史或肺癌家族史高風險族群。",
  "solve":"48歲女性可做子宮頸抹片；符合當時乳房X光年齡條件；每天1包×25年＝25包年，依原題當時LDCT資格未必達標；吸菸者符合口腔黏膜篩檢風險條件；大腸癌篩檢當時年齡門檻較高。因此原題答案D（1、2、4）。",
  "options":["A含3，依原題當時LDCT高風險資格不符。","B含3、5，且漏子宮頸抹片，不符。","C把乳癌漏掉且含大腸癌，錯。","D對：依原題年度條件為子宮頸、乳癌、口腔。","E多加5；48歲未達原題當時大腸癌篩檢年齡。"],
  "memory":"癌篩先看三件事：年齡、性別／器官、特殊風險；政策題一定標年份。"
}
});

